function httpPostGet(method,reqUrl,params,callback,async,timeout){var xhr=createHttpRequest();if(!xhr){return false}if(!IsUndefOrNull(timeout)){xhr.timeout=timeout;}if(async&&callback){xhr.onreadystatechange=function(){if(xhr.readyState===4){if(reqUrl==='login.cgi'){callback(str2var(xhr.responseText))}else{if(xhr.status===200){if(xhr.getResponseHeader("Content-Type")=='application/json')callback(str2var(xhr.responseText));else callback(xhr.responseText)}else if(xhr.status==600){return;}else{get_app_content(xhr.responseText)}}}}}var data=null;if(method.toUpperCase()=="POST"){data=params+'&page=inside';xhr.open(method,reqUrl,async);xhr.setRequestHeader('Content-type','application/x-www-form-urlencoded')}else{var timestamp=Date.parse(new Date());reqUrl=reqUrl+'?stamp='+timestamp+(params?'&'+params:'')+'&page=inside';xhr.open(method,reqUrl,async)};xhr.ontimeout=function(){xhr.abort();};xhr.onerror=function(){xhr.abort();};xhr.send(data);if(!async){return xhr.responseText}};
function serializeForm(formId){var elements=getElements(formId);var queryComponents=new Array();for(var i=0;i<elements.length;i++){var queryComponent=serializeElement(elements[i]);if(queryComponent)queryComponents.push(queryComponent)}return queryComponents.join('&')}
function serializeElement(element){var method=element.tagName.toLowerCase();var parameter=inputSelect(element);if(parameter){var key=encodeURIComponent(parameter[0]);if(key.length==0)return;if(parameter[1].constructor!=Array)parameter[1]=[parameter[1]];var values=parameter[1];var results=[];for(var i=0;i<values.length;i++){results.push(key+'='+encodeURIComponent(values[i]))}return results.join('&')}}
function getElements(formId){var form=getId(formId);var elements=new Array();var tagElements=form.getElementsByTagName('input');for(var j=0;j<tagElements.length;j++){elements.push(tagElements[j])}var selectTagElements=form.getElementsByTagName('select');for(var j=0;j<selectTagElements.length;j++){elements.push(selectTagElements[j])}return elements}
function inputSelect(element){if(element.tagName=='INPUT'){switch(element.type.toLowerCase()){case'submit':case'hidden':case'password':case'text':if(!element.disabled)return[element.name,element.value];break;case'checkbox':case'radio':if(!element.disabled)return inputSelector(element);break}}else if(element.tagName=='SELECT'){if(!element.disabled){if(element.multiple){var val="";for(var i=0;i<element.length;i++){if(element.options[i].selected){if(val=="")val+=element.options[i].value;else val+="_"+element.options[i].value}}return[element.name,val]}else return[element.name,element.value]}}return false}
